-- Curate Sweden into meaningful chronological periods.
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TEMP TABLE se_tree(concept_id TEXT PRIMARY KEY) WITHOUT ROWID;
WITH RECURSIVE t(id) AS (VALUES('unified:f026602f-cc16-5617-bba6-5fa90f489b0d') UNION SELECT p.concept_id FROM t JOIN concept_parent p ON p.parent_concept_id=t.id) INSERT INTO se_tree SELECT id FROM t;
INSERT OR IGNORE INTO source_selector(concept_id,system_id,selector,ordinal) SELECT 'unified:f026602f-cc16-5617-bba6-5fa90f489b0d',s.system_id,s.selector,COALESCE((SELECT max(x.ordinal)+1 FROM source_selector x WHERE x.concept_id='unified:f026602f-cc16-5617-bba6-5fa90f489b0d' AND x.system_id=s.system_id),0) FROM source_selector s WHERE s.concept_id='bokheim:history-lcc:a58c813d-c066-516e-a31a-ae88d8403af1';
INSERT OR IGNORE INTO concept VALUES
('bokheim:sweden:early','Early Sweden, to 1060'),('bokheim:history-lcc-full:c086cebb-2ed8-5c63-86f6-1a8229ec62c2','Prehistoric Sweden, to 750'),('bokheim:history-lcc-full:9709867b-bead-5789-92ae-99000fa03136','Viking Age, 750–1060'),
('bokheim:sweden:medieval','Medieval Sweden, 1060–1523'),('bokheim:sweden:early-kingdom','Early Kingdom, 1060–1234'),('bokheim:history-lcc-full:c9a7aa18-8ae9-50a0-b3d8-8caa75a1125c','Late Medieval Sweden, 1234–1397'),('bokheim:history-lcc-full:c0018aca-e0d7-59e6-b45c-269da2f67283','Kalmar Union, 1397–1523'),
('bokheim:history-lcc:c3a988b6-5259-5f31-9cc4-bbd8683b6585','Vasa Era, 1523–1654'),('bokheim:history-lcc:472da656-aa2b-5905-8e64-94b32799289a','Swedish Empire, 1654–1718'),('bokheim:sweden:liberty','Age of Liberty, 1718–1772'),('bokheim:sweden:gustavian','Gustavian Era, 1772–1809'),
('bokheim:sweden:constitutional','Constitutional Sweden, 1809–1914'),('bokheim:history-lcc:5546d066-7a0d-5a15-a652-28be900f49a0','Union with Norway, 1814–1905'),('bokheim:sweden:world-wars','World Wars Era, 1914–1945'),('bokheim:sweden:postwar','Postwar Sweden, 1945–1990'),('bokheim:sweden:contemporary','Contemporary Sweden, 1990–Present');
CREATE TEMP TABLE se_keep(concept_id TEXT PRIMARY KEY) WITHOUT ROWID;
INSERT INTO se_keep SELECT concept_id FROM concept WHERE concept_id='unified:f026602f-cc16-5617-bba6-5fa90f489b0d' OR concept_id LIKE 'bokheim:sweden:%' OR concept_id IN ('bokheim:history-lcc-full:c086cebb-2ed8-5c63-86f6-1a8229ec62c2','bokheim:history-lcc-full:9709867b-bead-5789-92ae-99000fa03136','bokheim:history-lcc-full:c9a7aa18-8ae9-50a0-b3d8-8caa75a1125c','bokheim:history-lcc-full:c0018aca-e0d7-59e6-b45c-269da2f67283','bokheim:history-lcc:c3a988b6-5259-5f31-9cc4-bbd8683b6585','bokheim:history-lcc:472da656-aa2b-5905-8e64-94b32799289a','bokheim:history-lcc:5546d066-7a0d-5a15-a652-28be900f49a0');
CREATE TEMP TABLE se_shared(concept_id TEXT PRIMARY KEY) WITHOUT ROWID;
WITH RECURSIVE s(id) AS (SELECT t.concept_id FROM se_tree t JOIN concept_parent p ON p.concept_id=t.concept_id WHERE p.parent_concept_id NOT IN (SELECT concept_id FROM se_tree) AND t.concept_id<>'unified:f026602f-cc16-5617-bba6-5fa90f489b0d' UNION SELECT p.concept_id FROM s JOIN concept_parent p ON p.parent_concept_id=s.id WHERE p.concept_id IN (SELECT concept_id FROM se_tree)) INSERT INTO se_shared SELECT id FROM s;
DELETE FROM concept_parent WHERE parent_concept_id IN (SELECT concept_id FROM se_tree);
DELETE FROM concept_parent WHERE concept_id IN (SELECT concept_id FROM se_tree WHERE concept_id NOT IN (SELECT concept_id FROM se_keep) AND concept_id NOT IN (SELECT concept_id FROM se_shared));
DELETE FROM concept WHERE concept_id IN (SELECT concept_id FROM se_tree WHERE concept_id NOT IN (SELECT concept_id FROM se_keep) AND concept_id NOT IN (SELECT concept_id FROM se_shared));
CREATE TEMP TABLE se_edge(child TEXT,parent TEXT,ord INTEGER,PRIMARY KEY(child,parent)) WITHOUT ROWID;
INSERT INTO se_edge VALUES
('bokheim:sweden:early','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',10),('bokheim:sweden:medieval','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',20),('bokheim:history-lcc:c3a988b6-5259-5f31-9cc4-bbd8683b6585','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',30),('bokheim:history-lcc:472da656-aa2b-5905-8e64-94b32799289a','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',40),('bokheim:sweden:liberty','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',50),('bokheim:sweden:gustavian','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',60),('bokheim:sweden:constitutional','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',70),('bokheim:sweden:world-wars','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',80),('bokheim:sweden:postwar','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',90),('bokheim:sweden:contemporary','unified:f026602f-cc16-5617-bba6-5fa90f489b0d',100),
('bokheim:history-lcc-full:c086cebb-2ed8-5c63-86f6-1a8229ec62c2','bokheim:sweden:early',10),('bokheim:history-lcc-full:9709867b-bead-5789-92ae-99000fa03136','bokheim:sweden:early',20),('bokheim:sweden:early-kingdom','bokheim:sweden:medieval',10),('bokheim:history-lcc-full:c9a7aa18-8ae9-50a0-b3d8-8caa75a1125c','bokheim:sweden:medieval',20),('bokheim:history-lcc-full:c0018aca-e0d7-59e6-b45c-269da2f67283','bokheim:sweden:medieval',30),('bokheim:history-lcc:5546d066-7a0d-5a15-a652-28be900f49a0','bokheim:sweden:constitutional',10);
INSERT INTO concept_parent(concept_id,parent_concept_id,ordinal,display_order) SELECT child,parent,COALESCE((SELECT max(ordinal)+1 FROM concept_parent WHERE concept_id=child),0),ord FROM se_edge;
UPDATE concept SET preferred_label=CASE concept_id WHEN 'bokheim:history-lcc-full:c086cebb-2ed8-5c63-86f6-1a8229ec62c2' THEN 'Prehistoric Sweden, to 750' WHEN 'bokheim:history-lcc-full:9709867b-bead-5789-92ae-99000fa03136' THEN 'Viking Age, 750–1060' WHEN 'bokheim:history-lcc-full:c9a7aa18-8ae9-50a0-b3d8-8caa75a1125c' THEN 'Late Medieval Sweden, 1234–1397' WHEN 'bokheim:history-lcc-full:c0018aca-e0d7-59e6-b45c-269da2f67283' THEN 'Kalmar Union, 1397–1523' WHEN 'bokheim:history-lcc:c3a988b6-5259-5f31-9cc4-bbd8683b6585' THEN 'Vasa Era, 1523–1654' WHEN 'bokheim:history-lcc:472da656-aa2b-5905-8e64-94b32799289a' THEN 'Swedish Empire, 1654–1718' WHEN 'bokheim:history-lcc:5546d066-7a0d-5a15-a652-28be900f49a0' THEN 'Union with Norway, 1814–1905' ELSE preferred_label END WHERE concept_id IN (SELECT concept_id FROM se_keep);
DROP TABLE se_edge; DROP TABLE se_shared; DROP TABLE se_keep; DROP TABLE se_tree;
COMMIT;
